import{_ as o,o as a,c as l,a2 as e}from"./chunks/framework.CdvW4CUT.js";const d=JSON.parse('{"title":"Swap 与内存回收（Memory Reclaim）技术总结","description":"","frontmatter":{},"headers":[],"relativePath":"notes/linux-kernel/memory/swap_memory_reclaim.md","filePath":"notes/linux-kernel/memory/swap_memory_reclaim.md"}'),r={name:"notes/linux-kernel/memory/swap_memory_reclaim.md"};function i(n,t,s,u,g,p){return a(),l("div",null,[...t[0]||(t[0]=[e(`<h1 id="swap-与内存回收-memory-reclaim-技术总结" tabindex="-1">Swap 与内存回收（Memory Reclaim）技术总结 <a class="header-anchor" href="#swap-与内存回收-memory-reclaim-技术总结" aria-label="Permalink to &quot;Swap 与内存回收（Memory Reclaim）技术总结&quot;">​</a></h1><blockquote><p><strong>报告对象</strong>：《Swap and Memory Reclaim — Squeezing Out More RAM》（KR2026） <strong>作者</strong>：Kairui Song（腾讯 · Tencent），kasong@tencent.com <strong>主题</strong>：Linux 内核 Swap 子系统的现代化改造，以及内存回收（Memory Reclaim / MGLRU）的最新演进 <strong>一句话概括</strong>：通过重构 Swap 元数据结构 + 优化内存冷热评估算法，让&quot;冷内存&quot;被高效挤出，从而在更少物理内存下归档缓存更多数据。</p></blockquote><hr><h2 id="一、为什么值得关注" tabindex="-1">一、为什么值得关注 <a class="header-anchor" href="#一、为什么值得关注" aria-label="Permalink to &quot;一、为什么值得关注&quot;">​</a></h2><p>这份 PPT 不是泛泛的技术科普，而是<strong>内核内存管理方向的一手工程实践</strong>。它回答了三个核心问题：</p><ol><li><strong>Swap 为什么&quot;又慢又乱&quot;？</strong> —— 历史包袱、多数据源耦合、锁竞争。</li><li><strong>怎么把它变干净？</strong> —— 用&quot;swap table&quot;把 1+2+8 字节的零散元数据合并为单条 8 字节项，以 2MB cluster 为管理单元。</li><li><strong>怎么找到真正该回收的&quot;冷页&quot;？</strong> —— 从经典 LRU 到 MGLRU，再到作者提出的 MGLRU-FG 频率增强方案。</li></ol><p>对从事内核开发、云原生基础设施、数据库/大数据底层优化的工程师，这份内容直接关系<strong>内存效率、吞吐与成本</strong>。</p><hr><h2 id="二、swap-基础概念梳理" tabindex="-1">二、Swap 基础概念梳理 <a class="header-anchor" href="#二、swap-基础概念梳理" aria-label="Permalink to &quot;二、Swap 基础概念梳理&quot;">​</a></h2><h3 id="_2-1-swap-是什么" tabindex="-1">2.1 Swap 是什么 <a class="header-anchor" href="#_2-1-swap-是什么" aria-label="Permalink to &quot;2.1 Swap 是什么&quot;">​</a></h3><p>Swap 允许<strong>使用超过物理内存的容量</strong>：把存储当 RAM 用，借用 CPU 无法直接寻址的资源（通过缺页中断）。如今日益普遍的是<strong>内存压缩（memory compression）</strong>，即用 CPU 周期换 RAM。它也是内存耗尽时（OOM 前）的最后防线。</p><h3 id="_2-2-swap-的工作机制" tabindex="-1">2.2 Swap 的工作机制 <a class="header-anchor" href="#_2-2-swap-的工作机制" aria-label="Permalink to &quot;2.2 Swap 的工作机制&quot;">​</a></h3><ul><li>用户态使用虚拟地址，CPU 走页表 → PTE 指向物理内存（Folio / 映射页）。</li><li>内核可以在用户态看到相同虚拟内存的前提下，灵活搬动物理内存。</li><li><strong>换出（Swap Out）</strong>： <ol><li>内核选择&quot;受害 Folio&quot;（victim folio）。</li><li>Swap 分配器在交换设备上分配一个 4K slot，用 swap entry（设备号 + 偏移）表示。</li><li>将该 Folio 从页表解除映射，把 swap entry 写入 PTE。</li><li>把内容写回 slot，释放物理 Folio。</li></ol></li><li><strong>换入（Swap In）</strong>： <ol><li>访问 swap entry 触发缺页中断。</li><li>内核分配新物理 Folio，读回内容，映射回页表，释放 swap slot。</li></ol></li></ul><h3 id="_2-3-现实的复杂性-为什么-没那么简单" tabindex="-1">2.3 现实的复杂性（为什么&quot;没那么简单&quot;） <a class="header-anchor" href="#_2-3-现实的复杂性-为什么-没那么简单" aria-label="Permalink to &quot;2.3 现实的复杂性（为什么&quot;没那么简单&quot;）&quot;">​</a></h3><ul><li><strong>多对一映射</strong>：多个 PTE 可指向同一 Folio（CoW、KSM），swap slot 同理，需要引用计数。</li><li><strong>Swap Cache</strong>：用于避免冗余 I/O 与并发同步；换入/换出时 Folio 驻留在 cache 中实现快速恢复。</li><li><strong>memcg 记账</strong>：每个 slot 需要记录归属的内存 cgroup。</li><li><strong>高并发高压</strong>：Swap 是 MM 核心，性能敏感、竞争激烈。</li></ul><p><strong>关键痛点（Slide 13）</strong>：历史脏数据越积越多——</p><table tabindex="0"><thead><tr><th>元数据</th><th>大小</th><th>说明</th></tr></thead><tbody><tr><td>swap_map（count）</td><td>1 字节/槽</td><td>静态，仅 6 bit 可用 + 溢出/同步标志</td></tr><tr><td>memcg id</td><td>2 字节/槽</td><td>静态</td></tr><tr><td>swap cache 指针/影子</td><td>8 字节</td><td>xarray（还有 overflow page、zeromap 等）</td></tr></tbody></table><p>结果：分配只是&quot;扫描静态 map&quot;，扩展性差；多数据源同步导致锁差、性能劣化、bug 多；静态数据空闲内存占用高。</p><hr><h2 id="三、swap-子系统现代化改造-作者的核心贡献" tabindex="-1">三、Swap 子系统现代化改造（作者的核心贡献） <a class="header-anchor" href="#三、swap-子系统现代化改造-作者的核心贡献" aria-label="Permalink to &quot;三、Swap 子系统现代化改造（作者的核心贡献）&quot;">​</a></h2><p>改造原文见 LWN：<a href="https://lwn.net/Articles/1056405/" target="_blank" rel="noreferrer">https://lwn.net/Articles/1056405/</a></p><h3 id="_3-1-第一步-cluster-分配器" tabindex="-1">3.1 第一步：Cluster 分配器 <a class="header-anchor" href="#_3-1-第一步-cluster-分配器" aria-label="Permalink to &quot;3.1 第一步：Cluster 分配器&quot;">​</a></h3><ul><li><strong>旧方案</strong>：围绕静态 swap map 构建，复杂、性能差；可选 2MB clustering，全局扫描、逻辑纠缠（PCP 随机化、SSD/HDD 区别）。</li><li><strong>新方案</strong>：<strong>强制 2MB swap cluster</strong>，所有 cluster 常驻链表；分配退化为&quot;查链表头&quot;。消除全局操作、重构锁以去除竞争。</li></ul><h3 id="_3-2-第二步-合并元数据-——-引入-swap-table" tabindex="-1">3.2 第二步：合并元数据 —— 引入 Swap Table <a class="header-anchor" href="#_3-2-第二步-合并元数据-——-引入-swap-table" aria-label="Permalink to &quot;3.2 第二步：合并元数据 —— 引入 Swap Table&quot;">​</a></h3><p>核心洞察：<strong>每个 slot 只可能处于三种状态之一</strong>（Free / Used-uncached / Used-cached，外加 Bad），所以 <strong>1 个 unsigned long（64 位）几乎足够表示一切</strong>。</p><p>编码示意：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* Free:    |--------------- 0 ---------------|      (空闲)</span></span>
<span class="line"><span>* Shadow:  |SWAP_COUNT|Z|---- SHADOW_VAL ----|1|   (换出-未缓存)</span></span>
<span class="line"><span>* PFN:     |SWAP_COUNT|Z|------ PFN ---------|10|  (已缓存)</span></span>
<span class="line"><span>* Pointer: |----------- Pointer ------------|100|  (保留)</span></span>
<span class="line"><span>* Bad:     |------------- 1 ----------------|1000| (坏槽)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>为什么能塞进去</strong>：</p><ul><li>未缓存槽存&quot;影子时间戳&quot;，64 位中可腾出 6 bit 作计数。</li><li>缓存槽直接存 PFN（52 位），上方位足够放计数。</li><li>既然 cluster 已成管理单位，每个 cluster 只用<strong>一个 unsigned long 数组</strong>同时承担计数与缓存。</li></ul><p><strong>收益</strong>：</p><ul><li>仅在使用中的 cluster 才分配表，空闲 cluster 可释放，<strong>内存占用更低</strong>，表精确 4K（8×512）。</li><li>1 字节 swap_map + 8 字节 swap cache <strong>合并为一条 8 字节 swap table entry</strong>。</li><li>性能更好、数据源更紧凑、<strong>不再有同步负担与 hacks</strong>。</li><li>memcg 数组拆分为 per-cluster 表，<strong>空闲内存占用趋近于零</strong>。</li></ul><blockquote><p><strong>结果</strong>：swap-in 现在完全运行在单一、基于 cluster 的数据源上，消除了历史 workaround，维护开销更低、内存更省、性能更高，内核内部 API 也更干净。</p></blockquote><h3 id="_3-3-观点-swap-越来越-有助性能" tabindex="-1">3.3 观点：Swap 越来越&quot;有助性能&quot; <a class="header-anchor" href="#_3-3-观点-swap-越来越-有助性能" aria-label="Permalink to &quot;3.3 观点：Swap 越来越&quot;有助性能&quot;&quot;">​</a></h3><ul><li>Swap 曾因&quot;慢&quot;而口碑差，但<strong>存储变快、Swap/压缩变快</strong>，情况已改变。</li><li>内存压缩用 CPU 换 RAM；机器上常有大量<strong>一次性使用的冷匿名内存</strong>。</li><li><strong>开启 Swap 能让内核缓存更多热数据</strong> —— 能更高效地跑 git log / grep 等 IO 密集任务。</li></ul><h3 id="_3-4-swap-未来方向" tabindex="-1">3.4 Swap 未来方向 <a class="header-anchor" href="#_3-4-swap-未来方向" aria-label="Permalink to &quot;3.4 Swap 未来方向&quot;">​</a></h3><ul><li>更好的 Readahead、更好的 THP 换入/换出</li><li>在缺页发生前避免缺页</li><li>Tiering（分层）、Resizing、Balancing、Migration、IO 批处理</li><li>更好的非物理 Swap</li><li><strong>找到正确的 Folio 去换出</strong>（衔接下一章）</li></ul><hr><h2 id="四、内存回收-memory-reclaim-与冷热评估" tabindex="-1">四、内存回收（Memory Reclaim）与冷热评估 <a class="header-anchor" href="#四、内存回收-memory-reclaim-与冷热评估" aria-label="Permalink to &quot;四、内存回收（Memory Reclaim）与冷热评估&quot;">​</a></h2><h3 id="_4-1-内存回收全景" tabindex="-1">4.1 内存回收全景 <a class="header-anchor" href="#_4-1-内存回收全景" aria-label="Permalink to &quot;4.1 内存回收全景&quot;">​</a></h3><p>内存回收比 Swap 更宽泛。用户态内存大致两类：</p><ul><li><strong>Anon Folio</strong> → Swap 支撑 → 换出</li><li><strong>File Folio</strong> → Page Cache → 干净则直接丢弃（drop）</li><li>Shmem 及其他</li></ul><p><strong>核心思想：&quot;空闲内存是浪费，页缓存留到内存压力到来&quot;</strong>。目标是在压力下找出 RAM 里的&quot;冷部分&quot;来驱逐。</p><h3 id="_4-2-冷热度-hotness-信息从哪来" tabindex="-1">4.2 冷热度（Hotness）信息从哪来 <a class="header-anchor" href="#_4-2-冷热度-hotness-信息从哪来" aria-label="Permalink to &quot;4.2 冷热度（Hotness）信息从哪来&quot;">​</a></h3><ul><li><strong>Mapped（anon/file）</strong>：PTE Access Bit（CPU 访问时置位）</li><li><strong>Unmapped（file）</strong>：<code>folio_mark_accessed()</code>（内核主动调用）</li><li><strong>时间局部性</strong>（LRU）：最近分配的 Folio 更可能被再用</li><li><strong>Refault</strong>：被驱逐的 Folio 在原始映射处留下&quot;时间戳&quot;</li><li>其他：madv、fadv 提示</li></ul><h3 id="_4-3-评估热度的难点" tabindex="-1">4.3 评估热度的难点 <a class="header-anchor" href="#_4-3-评估热度的难点" aria-label="Permalink to &quot;4.3 评估热度的难点&quot;">​</a></h3><ul><li><strong>PTE Access 是&quot;粘性的&quot;</strong>：布尔位、多次访问难区分；收集成本高（RMAP 反向遍历逐个 PTE，还须修改页表重置）。</li><li><strong>folio_mark_accessed()</strong> 位于极热路径，必须足够快。</li><li><strong>LRU 的冷缓存污染（Cold Cache Pollution）</strong>：一次性的冷缓存爆发会把热缓存挤出去。</li><li><strong>LFU 的陈旧缓存污染（Stale Cache Pollution）</strong>：历史热页滞留过久，工作集无法更新，且扫描排序成本高。</li></ul><h3 id="_4-4-经典方案-clru-active-inactive-双链表-lru" tabindex="-1">4.4 经典方案：CLRU（Active/Inactive 双链表 LRU） <a class="header-anchor" href="#_4-4-经典方案-clru-active-inactive-双链表-lru" aria-label="Permalink to &quot;4.4 经典方案：CLRU（Active/Inactive 双链表 LRU）&quot;">​</a></h3><ul><li>经内核数十载打磨的&quot;经典 LRU&quot;。</li><li>活跃 + 非活跃两条链表区分工作集；一次性 Folio 留在 inactive。</li><li>需要<strong>两次访问</strong>才提升到 active。</li><li><strong>缺点</strong>：升降级都需 LRU 锁、两次 RMAP 遍历、只有两级热度、folio_mark_accessed() 与锁的高频开销。</li></ul><h3 id="_4-5-mglru-multi-gen-lru-——-框架级方案" tabindex="-1">4.5 MGLRU（Multi-Gen LRU）—— 框架级方案 <a class="header-anchor" href="#_4-5-mglru-multi-gen-lru-——-框架级方案" aria-label="Permalink to &quot;4.5 MGLRU（Multi-Gen LRU）—— 框架级方案&quot;">​</a></h3><p><strong>核心设计</strong>：4 个 Gen + 4 个 Tier；Folio flags 中 3(gen)+2(tier) bit；配合<strong>页表遍历器、惰性提升、Rmap Lookaround、Bloom filter、PID feedback</strong>。它是一个可定制策略的<strong>框架</strong>。</p><p><strong>Aging（老化）机制</strong>：</p><ol><li>直接遍历页表，批量收集并重置访问位；&quot;惰性提升&quot;（仅标志位、无锁）把访问的 Folio 提升到最新 Gen。</li><li>压力下启动 aging，生成新 Gen（嵌入时间戳）。</li><li>驱逐只发生在<strong>最老 Gen 的尾部</strong>；被惰性提升的 Folio 看到属于更新 Gen 就&quot;只搬不移&quot;。</li><li>Gen 耗尽即&quot;丢弃&quot;——零成本，无链表搬移；用<strong>滑动窗口</strong>持续滚动。</li><li><strong>应对庞大地址空间</strong>：aging 也是惰性的，可延迟到只剩 2 Gen；用 <strong>Bloom filter</strong> 识别热区，只遍历热区，热点漂移时更新/丢弃对应 bit。</li><li>RMAP 仍作补充：更新 Bloom filter、对相邻 PTE 做 lookaround（PMD 内空间局部性批量提升）。</li></ol><p><strong>Tiering（分层 / PID 保护）</strong>：</p><ul><li>用于保护 <code>folio_mark_accessed()</code>（无映射文件的访问）。</li><li>内核感知 refault（被驱逐后返回的 Folio，经 shadow 识别）。</li><li>某 tier refault 率高（refault/eviction）→ 驱逐时保护，提升 1 Gen；refault 率在 aging 时软重置。</li></ul><p><strong>MGLRU 的已知问题（Slide 49）</strong>：</p><ul><li>Unmapped file cache 极常见，PID 保护是它们唯一的提升途径，但只 +1 Gen 而 mapped 直接提到最新 Gen → <strong>文件页被过度回收</strong>，破坏 LRU 规则，造成陈旧缓存污染。</li><li>访问 ≥8 次的 Folio 无法再区分。</li><li>对 anon/mapped Folio 适配不佳，页表遍历器没有很好利用 tier。</li></ul><h3 id="_4-6-mglru-fg-作者的频率增强扩展" tabindex="-1">4.6 MGLRU-FG（作者的频率增强扩展） <a class="header-anchor" href="#_4-6-mglru-fg-作者的频率增强扩展" aria-label="Permalink to &quot;4.6 MGLRU-FG（作者的频率增强扩展）&quot;">​</a></h3><p><strong>思路</strong>：把惰性主动提升也应用到 <code>folio_mark_accessed()</code>/tier，让 tiering 成为<strong>统一的热度基线</strong>，并与频率结合。</p><ul><li><strong>冷缓存污染</strong>：冷缓存停留在低 Gen，永不污染新 Gen。</li><li><strong>热缓存污染</strong>：aging 以零成本降级所有 Folio；驱逐纯按 LRU 顺序，新提升/新分配的 Folio 总是最后被回收。</li><li>初步测试效果很好，RFC 已发布。</li></ul><h3 id="_4-7-内存回收的其他部分与议题" tabindex="-1">4.7 内存回收的其他部分与议题 <a class="header-anchor" href="#_4-7-内存回收的其他部分与议题" aria-label="Permalink to &quot;4.7 内存回收的其他部分与议题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>议题</th><th>说明</th></tr></thead><tbody><tr><td><strong>Swappiness</strong></td><td>Anon 与 File 分属两条 LRU；CLRU 按 swappiness 平衡回收，MGLRU 对两类同步 Gen、回收 refault 率最低的最老 Gen。swappiness 改进进行中。</td></tr><tr><td><strong>避免 Thrashing</strong></td><td>及时唤醒 OOM Killer；MGLRU 用时间戳做 TTL。</td></tr><tr><td><strong>Refault Distance</strong></td><td>用 shadow 里的&quot;时间戳&quot;补充热度（被驱逐出内存多久/多远）；MGLRU 改用 Gen 编号估计，但 Refault Distance 也可用于 MGLRU（RFC 已发布）。</td></tr><tr><td><strong>Throttling / Cgroup Balancing</strong></td><td>限流与 cgroup 均衡。</td></tr></tbody></table><hr><h2 id="五、技术演进趋势与我的思考" tabindex="-1">五、技术演进趋势与我的思考 <a class="header-anchor" href="#五、技术演进趋势与我的思考" aria-label="Permalink to &quot;五、技术演进趋势与我的思考&quot;">​</a></h2><h3 id="_5-1-趋势一-从-向外借内存-到-向上挤内存" tabindex="-1">5.1 趋势一：从&quot;向外借内存&quot;到&quot;向上挤内存&quot; <a class="header-anchor" href="#_5-1-趋势一-从-向外借内存-到-向上挤内存" aria-label="Permalink to &quot;5.1 趋势一：从&quot;向外借内存&quot;到&quot;向上挤内存&quot;&quot;">​</a></h3><p>Swap 的本质正从&quot;救命的二次存储器&quot;演变为&quot;<strong>主动的压缩冷存储层</strong>&quot;。叠加内存压缩，趋势是：</p><ul><li>冷匿名页被压缩后驻留内存，而非写回磁盘 → <strong>速度与容量兼得</strong>。</li><li>开启 Swap + 良好回收策略，对 IO 密集应用（git log / grep / 大数据）是<strong>性能净增益</strong>，而非传统的谈之色变。</li></ul><h3 id="_5-2-趋势二-元数据从-多处零散-走向-单源紧凑" tabindex="-1">5.2 趋势二：元数据从&quot;多处零散&quot;走向&quot;单源紧凑&quot; <a class="header-anchor" href="#_5-2-趋势二-元数据从-多处零散-走向-单源紧凑" aria-label="Permalink to &quot;5.2 趋势二：元数据从&quot;多处零散&quot;走向&quot;单源紧凑&quot;&quot;">​</a></h3><p>作者用 Swap Table 把 1+2+8 字节的碎片化元数据合并为单条 64 位项，以 2MB cluster 为管理单元，做到&quot;只在用的时候才占用、空闲趋零&quot;。这是一条可复用的工程范式：</p><blockquote><p><strong>合并麻雀式数据结构 → 以较大管理单元摊销固定开销 → 按需分配释放</strong>。</p></blockquote><p>内核内存管理的许多子系统（如内存压测、热页追踪）都在沿这一方向收敛。</p><h3 id="_5-3-趋势三-冷热评估从-两级粗粒度-走向-多代多级-频率" tabindex="-1">5.3 趋势三：冷热评估从&quot;两级粗粒度&quot;走向&quot;多代多级 + 频率&quot; <a class="header-anchor" href="#_5-3-趋势三-冷热评估从-两级粗粒度-走向-多代多级-频率" aria-label="Permalink to &quot;5.3 趋势三：冷热评估从&quot;两级粗粒度&quot;走向&quot;多代多级 + 频率&quot;&quot;">​</a></h3><ul><li>CLRU 只有 Active/Inactive 两级，MGLRU 引入 4 Gen + 4 Tier，再到 <strong>MGLRU-FG 叠加频率（frequency）</strong>。</li><li>语义上就是从&quot;是否热&quot;走向&quot;多热、热了多久、被访问多少次&quot;。</li><li>关键创新点：<strong>惰性提升（lazy promotion）、页表直扫（避免 RMAP）、Bloom filter 定位热区、refault 反馈闭环</strong> —— 用&quot;少扫描、多推测、反馈校正&quot;换取性能。</li></ul><h3 id="_5-4-趋势四-个性化策略-vs-通用默认的平衡" tabindex="-1">5.4 趋势四：个性化策略 vs 通用默认的平衡 <a class="header-anchor" href="#_5-4-趋势四-个性化策略-vs-通用默认的平衡" aria-label="Permalink to &quot;5.4 趋势四：个性化策略 vs 通用默认的平衡&quot;">​</a></h3><ul><li>MGLRU 是&quot;框架&quot;，允许自定义策略，但<strong>不可能为每个应用单独打磨策略</strong>。</li><li>因此作者强调<strong>改进默认实现</strong>（<code>/sys/kernel/debug/lru_gen_full</code> 可观测调参），这也是内核演进的主流哲学：默认稳健 + 可调优 + 可观测。</li></ul><h3 id="_5-5-我的几点判断" tabindex="-1">5.5 我的几点判断 <a class="header-anchor" href="#_5-5-我的几点判断" aria-label="Permalink to &quot;5.5 我的几点判断&quot;">​</a></h3><ol><li><strong>&quot;空闲内存是浪费，冷内存也是浪费&quot;</strong> 是全文的价值观内核。未来云原生/容器密度提升，很大程度上要靠更聪明的内存回收而非单纯加内存。</li><li>Swap 的&quot;污名&quot;正在被性能数据扭转，但<strong>正确的驱逐策略</strong>（MGLRU-FG 这类频率感知）仍是决定收益的关键变量 —— 选错 victim 反而拖累。</li><li>元数据紧凑化（swap table）带来的不只是内存节省，更是<strong>锁竞争与同步复杂度的下降</strong>，这在多核高并发下是隐性但巨大的吞吐红利。</li><li>内存回收正从&quot;LRU 经验主义&quot;走向&quot;可反馈、可观测、可学习的自适应系统&quot;（refault/PID 反馈 + Bloom filter + 时间戳）。未来可能与内核外（DAMON 等主动式）能力进一步融合。</li></ol><hr><h2 id="六、金句摘录" tabindex="-1">六、金句摘录 <a class="header-anchor" href="#六、金句摘录" aria-label="Permalink to &quot;六、金句摘录&quot;">​</a></h2><blockquote><p>&quot;All problems in computer science can be solved by another level of indirection, except for the problem of too many layers of indirection.&quot; —— 讽刺旧 Swap-in 栈层层包裹的 workaround</p></blockquote><blockquote><p>&quot;Free memory is wasted memory. Cold memory is wasted memory.&quot; —— 全文要义：榨出更多可用 RAM</p></blockquote><blockquote><p>&quot;Archive more using less memory!&quot; —— Swap + 内存回收的最终价值主张</p></blockquote><hr><h2 id="七、延伸阅读" tabindex="-1">七、延伸阅读 <a class="header-anchor" href="#七、延伸阅读" aria-label="Permalink to &quot;七、延伸阅读&quot;">​</a></h2><ul><li>LWN 文章：Modernizing the Swap Subsystem — <a href="https://lwn.net/Articles/1056405/" target="_blank" rel="noreferrer">https://lwn.net/Articles/1056405/</a></li><li>Linux 内核 MGLRU（<code>mm/vmscan.c</code>、<code>lru_gen_*</code>）实现文档</li><li><code>/sys/kernel/debug/lru_gen_full</code> 可观测接口</li></ul>`,84)])])}const h=o(r,[["render",i]]);export{d as __pageData,h as default};
